/**
 * MolCrafts shared design tokens (v0 scaffold).
 * Products import this file then override product-only variables if needed.
 *
 * Naming aligns with molexp/molvis control vocabulary (accent, control radius).
 */

:root {
  /* Surfaces */
  --background: oklch(0.99 0 0);
  --foreground: oklch(0.2 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.2 0 0);
  --muted: oklch(0.96 0 0);
  --muted-foreground: oklch(0.45 0 0);
  --accent: oklch(0.55 0.12 264);
  --accent-foreground: oklch(0.99 0 0);
  --accent-hover: oklch(0.5 0.12 264);
  --border: oklch(0.9 0 0);
  --input: oklch(0.9 0 0);
  --ring: oklch(0.55 0.12 264);
  --destructive: oklch(0.55 0.2 25);
  --destructive-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.96 0 0);
  --secondary-foreground: oklch(0.25 0 0);

  /* Radius / control (products map to h-control utilities) */
  --radius: 0.5rem;
  --radius-control: 0.375rem;

  /* Status (placeholders — v1 aligns exact product values) */
  --status-running: oklch(0.55 0.12 250);
  --status-succeeded: oklch(0.55 0.14 150);
  --status-failed: oklch(0.55 0.2 25);
  --status-warning: oklch(0.7 0.14 80);
}

.dark {
  --background: oklch(0.16 0 0);
  --foreground: oklch(0.95 0 0);
  --card: oklch(0.2 0 0);
  --card-foreground: oklch(0.95 0 0);
  --muted: oklch(0.24 0 0);
  --muted-foreground: oklch(0.65 0 0);
  --accent: oklch(0.65 0.12 264);
  --accent-foreground: oklch(0.12 0 0);
  --accent-hover: oklch(0.7 0.12 264);
  --border: oklch(0.3 0 0);
  --input: oklch(0.3 0 0);
  --ring: oklch(0.65 0.12 264);
  --destructive: oklch(0.55 0.18 25);
  --destructive-foreground: oklch(0.98 0 0);
  --secondary: oklch(0.24 0 0);
  --secondary-foreground: oklch(0.95 0 0);
}
